#include <inttypes.h>
#include <stdio.h>
#include <stdint.h>
#include "memory_map.h"
#include "core_v5.h"

#ifndef NDS_MHVM_CFG
		#define NDS_MHVM_CFG 0xFD0
#endif

#ifndef NDS_MHVMB
		#define NDS_MHVMB 0xFD1
#endif

#define xlen_t unsigned long long

#define MHVM_CFG_SZ_FIELD 0
#define MHVM_CFG_BANK_FIELD 8
#define MHVM_CFG_BA_FIELD 16
#define MHVM_CFG_SZ_MSK ((1ULL << 8) - 1)
#define MHVM_CFG_BANK_MSK (1ULL << 8)
#define MHVM_CFG_BA_MSK (((1ULL << 5) - 1) << MHVM_CFG_BA_FIELD)

int main(void)
{
		xlen_t hart_id = read_csr(NDS_MHARTID);
		uintptr_t hvm_base = (uintptr_t)read_csr(NDS_MHVMB);
		xlen_t hvm_cfg = read_csr(NDS_MHVM_CFG);
		xlen_t hvm_sz = hvm_cfg & MHVM_CFG_SZ_MSK;

		printf("hart_id = %" PRIuPTR ", hvm_base = %" PRIxPTR ", hvm_sz = %llx\n",
		       (uintptr_t)hart_id, hvm_base, (unsigned long long)hvm_sz);

		// trigger custom master to send data via subordinate port
		SIM_CONTROL_REG = TEST_HVM;

		// wait for the HVM transfer completes
		for(int i = 0; i < 32; i++) {
				asm volatile("nop");
		}

		// read HVM (first read)
		uintptr_t start = hvm_base;
		uintptr_t end = start + 32;

		printf("First read - Initial HVM data:\n");
		for (uintptr_t addr = start; addr < end; addr += 4) {
				unsigned int data = *(unsigned int *)addr;
				printf("addr = %" PRIxPTR ", data = %x\n", addr, data);
		}

		// write to HVM
		printf("\nModifying HVM data...\n");
		for (uintptr_t addr = start; addr < end; addr += 4) {
				unsigned int original_data = *(unsigned int *)addr;
				unsigned int modified_data = original_data + 0x10;
				*(unsigned int *)addr = modified_data;
				printf("Modified addr %" PRIxPTR ": %x -> %x\n", addr, original_data, modified_data);
		}

		// read HVM again (second read)
		printf("\nSecond read - Modified HVM data:\n");
		for (uintptr_t addr = start; addr < end; addr += 4) {
				unsigned int data = *(unsigned int *)addr;
				printf("addr = %" PRIxPTR ", data = %x\n", addr, data);
		}

		return 0;
}
